result:
.pege-title {
  padding: 15px 0;
  font-weight: 500;
  color: #333;
  font-size: 17px;
  line-height: 17px;
  text-align: center;
}

.jianbian1 {
  background: linear-gradient(90deg, #f4dfaf 0%, #d0a15b 100%);
}

.jianbian2 {
  background: linear-gradient(180deg, #faeed9 0%, #ffffff 100%);
  width: 710px;
  left: 50%;
  transform: translateX(-50%);
}

.border_top {
  border-top: 1px solid rgba(0, 0, 0, 0.08);
}

.SemiBold {
  font-family: SemiBold;
}

.v-Line {
  width: 1px;
  height: 20px;
  background: #eee;
}

.span-primary-con {
  color: var(--div-theme);
}

.user-wrapper {
  padding: 20px 20px 20px 16px;

  .avatar {
    width: 68px;
    height: 68px;
    border-radius: 50%;
  }

  .name-wrap {
    flex: 1;
    padding: 0 12px;
    color: #333333;
  }

  .name {
    font-weight: 500;
    font-size: 16px;
    line-height: 22px;
  }

  .phone {
    margin-top: 5px;
    font-size: 12px;
    line-height: 17px;
  }

  .mobiconfont {
    align-self: flex-start;
    margin-top: 11px;
  }
}

.promotion-wrapper {
  padding: 0 24px;
  font-size: 13px;
  line-height: 18px;
  color: #999999;

  .value {
    margin-left: 4px;
    font-family: SemiBold;
    font-weight: 600;
    font-size: 14px;
    color: #333333;
  }
}

.member-wrapper {
  margin: 14px 10px 10px;
  color: #7e4b06;

  .card {
    position: relative;
    border-radius: 16px;
    margin-bottom: -14px;
    background: linear-gradient(-270deg, #f4dfaf 0%, #d0a15b 100%);

    .top {
      padding: 12px 17px;
    }

    .name-wrap {
      flex: 1;
      font-size: 12px;
      line-height: 12px;
    }

    .name {
      margin-bottom: 2px;
      font-weight: 700;
      font-size: 17px;
      line-height: 24px;

      .mobiconfont {
        margin-right: 6px;
        font-size: 18px;
      }
    }

    .icon-wrap {
      font-size: 12px;
      line-height: 12px;

      + .icon-wrap {
        margin-left: 16px;
      }
    }

    .icon {
      width: 20px;
      height: 20px;
      border-radius: 50%;
      margin: 0 auto 3px;
      background-color: #eccd8b;
      text-align: center;
      line-height: 20px;

      .mobiconfont {
        font-size: 12px;
      }
    }

    .bottom {
      position: relative;
      padding: 8px 17px;
      font-size: 12px;

      &::before {
        content: '';
        position: absolute;
        top: 0;
        right: 17px;
        left: 17px;
        height: 1px;
        background-color: rgba(0, 0, 0, 0.08);
      }
    }

    .span {
      padding-left: 57x;
    }

    .button {
      height: 24px;
      padding: 0 12px;
      border-radius: 12px;
      background-color: #eccd8b;
      font-weight: 500;
      line-height: 24px;
    }
  }

  .grow {
    padding: 25px 20px 10px;
    border-radius: 16px;
    background: linear-gradient(180deg, #faeed9 0%, #ffffff 100%);

    .span {
      flex: 1;
      padding-left: 8px;
    }
  }
}

.service {
  .image {
    width: 24px;
    height: 24px;
  }
}

.order-wrapper {
  .image {
    width: 24px;
    height: 24px;
  }
}
